/* updateMasterMdCpAgntcmpyInfoAlterPopAcntsupl */
UPDATE ACNTSUPL SET									
	PAY_TERMS				= #{st_pay_terms},
	PAY_TYPE					= #{st_pay_type},
	BANK_CD					= #{st_bank_cd},
	BANK_ACCOUNT_NO	= #{st_hash_bank_account_no},


	DEPOSITOR				= #{st_depositor}
WHERE SUPPLIER			= #{com_code}


/* deleteMasterMdCpAgntcmpyInfoAlterPopAvl */
UPDATE ICOMCMPY SET
	AVL_FLAG = #{st_avl_flag},
	AVL_CREATE_ID = #{st_user_id},
	AVL_CREATE_DATE = SYSDATE
WHERE COM_CODE =#{com_code}


/* deleteMasterMdCpAgntcmpyInfoAlterPopCmpy */
UPDATE ICOMCMPY SET
	STATUS				= 'D',
	CHANGE_DATE		= TO_CHAR(SYSDATE,'YYYYMMDD'),
	CHANGE_TIME		= TO_CHAR(SYSDATE,'HH24MISS'),
	CHANGE_USER_ID	= #{st_user_id}
WHERE COM_CODE		= #{com_code}


/* deleteMasterMdCpAgntcmpyInfoAlterPopUsr */
UPDATE ICOMLUSR SET
        STATUS		= 'D'
WHERE COM_CODE	= #{com_code}

